def ideal_gas_mass(formula=None, P=None, V=None, T=None):
    """Mass of a gas sample (ideal gas). The mass of a named gas that fills a volume at a given pressure and temperature.
    Formula: m = \\frac{PV}{RT}\\,M
    Inputs:
        formula: formula of the gas
        P: pressure
        V: volume
        T: temperature
    Outputs: m (mass of gas), n (amount of gas)
    See also: help("ideal_gas_mass")
    """
    given = {k: v for k, v in dict(formula=formula, P=P, V=V, T=T).items() if v is not None}
    return _P.solve("ideal_gas_mass", **given)

def ideal_gas_moles(P=None, V=None, T=None):
    """Ideal gas law: amount. The amount (moles) of an ideal gas from its pressure, volume and temperature.
    Formula: n = \\frac{PV}{RT}
    Inputs:
        P: pressure
        V: volume
        T: temperature
    Outputs: n (amount of gas)
    See also: help("ideal_gas_moles")
    """
    given = {k: v for k, v in dict(P=P, V=V, T=T).items() if v is not None}
