def molecular_formula(empirical=None, M=None):
    """Molecular formula from the empirical formula. The molecular formula from an empirical formula and the molar mass.
    Formula: n = \\frac{M}{M_{\\text{empirical}}}
    Inputs:
        empirical: empirical formula
        M: molar mass of the compound
    Outputs: multiple (whole-number multiple n), formula (molecular formula)
    See also: help("molecular_formula")
    """
    given = {k: v for k, v in dict(empirical=empirical, M=M).items() if v is not None}
    return _P.solve("molecular_formula", **given)

def moles_from_mass(formula=None, m=None):
    """Moles from a mass. The amount of substance (and number of formula units) in a given mass of a compound.
    Formula: n = \\frac{m}{M}
    Inputs:
        formula: chemical formula
        m: mass of the sample
    Outputs: n (amount of substance), N (number of formula units), M (molar mass)
    See also: help("moles_from_mass")
    """
    given = {k: v for k, v in dict(formula=formula, m=m).items() if v is not None}
    return _P.solve("moles_from_mass", **given)

def moles_from_particles(N=None):
    """Moles from a number of particles. The amount of substance that contains a given number of particles.
    Formula: n = \\frac{N}{N_A}
    Inputs:
        N: number of particles
    Outputs: n (amount of substance)
    See also: help("moles_from_particles")
    """
    given = {k: v for k, v in dict(N=N).items() if v is not None}
    return _P.solve("moles_from_particles", **given)

def nernst_potential(E0=None, n=None, Q=None, T=None):
    """Nernst equation. The cell potential at non-standard conditions from E°, the electrons transferred and the reaction quotient.
    Formula: E = E^\\circ - \\frac{RT}{nF}\\ln Q
    Inputs:
        E0: standard cell potential
        n: electrons transferred
        Q: reaction quotient
        T: temperature
    Outputs: E (cell potential)
    See also: help("nernst_potential")
    """
    given = {k: v for k, v in dict(E0=E0, n=n, Q=Q, T=T).items() if v is not None}
    return _P.solve("nernst_potential", **given)

def osmotic_pressure(i=None, c=None, T=None):
    """Osmotic pressure. The osmotic pressure of a dilute solution (van 't Hoff equation).
    Formula: \\Pi = i c R T
    Inputs:
        i: van 't Hoff factor
        c: molar concentration
        T: temperature
    Outputs: Pi (osmotic pressure), Pi_atm (in atm)
    See also: help("osmotic_pressure")
    """
    given = {k: v for k, v in dict(i=i, c=c, T=T).items() if v is not None}
    return _P.solve("osmotic_pressure", **given)

def partial_pressure(x=None, P_total=None):
    """Partial pressure (Dalton's law). The partial pressure of a gas in a mixture from its mole fraction and the total pressure.
    Formula: p_i = x_i P_{\\text{total}}
    Inputs:
        x: mole fraction of the gas
        P_total: total pressure
    Outputs: p (partial pressure)
    See also: help("partial_pressure")
    """
    given = {k: v for k, v in dict(x=x, P_total=P_total).items() if v is not None}
    return _P.solve("partial_pressure", **given)

def particles_from_mass(formula=None, m=None):
    """Number of molecules in a mass. The number of molecules (formula units) in a given mass of a compound.
    Formula: N = \\frac{m}{M} N_A
    Inputs:
        formula: chemical formula
        m: mass of the sample
    Outputs: N (number of molecules / formula units), n (amount of substance)
    See also: help("particles_from_mass")
    """
    given = {k: v for k, v in dict(formula=formula, m=m).items() if v is not None}
    return _P.solve("particles_from_mass", **given)

def particles_from_moles(n=None):
    """Number of particles in an amount. The number of particles in a given amount of substance (Avogadro's number).
    Formula: N = n N_A
    Inputs:
        n: amount of substance
    Outputs: N (number of particles)
    See also: help("particles_from_moles")
    """
    given = {k: v for k, v in dict(n=n).items() if v is not None}
    return _P.solve("particles_from_moles", **given)

def percent_yield(equation=None, reactant=None, m=None, product=None, actual=None):
    """Percent yield of a reaction. The percent yield from the mass of reactant used and the mass of product obtained.
    Formula: \\%\\,\\text{yield} = \\frac{m_{\\text{actual}}}{m_{\\text{theoretical}}} \\times 100
    Inputs:
        equation: the reaction (balanced or not)
        reactant: the reactant whose mass is given
        m: mass of the reactant
        product: the product obtained
        actual: actual mass of product obtained
    Outputs: percent_yield (percent yield (%)), theoretical_mass (theoretical mass of product)
    See also: help("percent_yield")
    """
    given = {k: v for k, v in dict(equation=equation, reactant=reactant, m=m, product=product, actual=actual).items() if v is not None}
    return _P.solve("percent_yield", **given)

def ph_diprotic_acid(Ka1=None, Ka2=None, c=None):
    """pH of a diprotic acid. The pH of a diprotic acid H2A from both dissociation constants, solved exactly.
    Formula: [\\mathrm{H^+}] = C\\frac{K_1[\\mathrm{H^+}] + 2K_1K_2}{[\\mathrm{H^+}]^2 + K_1[\\mathrm{H^+}] + K_1K_2} + \\frac{K_w}{[\\mathrm{H^+}]}
    Inputs:
        Ka1: first dissociation constant
        Ka2: second dissociation constant
        c: acid concentration
    Outputs: pH (pH)
    See also: help("ph_diprotic_acid")
    """
    given = {k: v for k, v in dict(Ka1=Ka1, Ka2=Ka2, c=c).items() if v is not None}
    return _P.solve("ph_diprotic_acid", **given)

def ph_from_hydronium(h=None):
    """pH from the hydronium concentration. pH, pOH and [OH-] from the hydronium (hydrogen ion) concentration at 25 °C.
    Formula: \\mathrm{pH} = -\\log_{10}[\\mathrm{H_3O^+}]
    Inputs:
        h: hydronium ion concentration
    Outputs: pH (pH), pOH (pOH), oh ([OH-])
    See also: help("ph_from_hydronium")
    """
    given = {k: v for k, v in dict(h=h).items() if v is not None}
    return _P.solve("ph_from_hydronium", **given)

def ph_from_hydroxide(oh=None):
    """pH from the hydroxide concentration. pOH and pH from the hydroxide ion concentration at 25 °C.
    Formula: \\mathrm{pH} = 14 + \\log_{10}[\\mathrm{OH^-}]
    Inputs:
        oh: hydroxide ion concentration
    Outputs: pH (pH), pOH (pOH)
    See also: help("ph_from_hydroxide")
    """
    given = {k: v for k, v in dict(oh=oh).items() if v is not None}
    return _P.solve("ph_from_hydroxide", **given)

def ph_salt_of_weak_acid(Ka=None, c=None):
    """pH of a salt of a weak acid. The pH of a solution of a salt of a weak acid and a strong base (e.g. sodium acetate) from the acid's Ka.
    Formula: K_b = \\frac{K_w}{K_a}
    Inputs:
        Ka: acid dissociation constant
        c: salt concentration
    Outputs: pH (pH), Kb (Kb of the anion (Kw/Ka))
    See also: help("ph_salt_of_weak_acid")
    """
    given = {k: v for k, v in dict(Ka=Ka, c=c).items() if v is not None}
    return _P.solve("ph_salt_of_weak_acid", **given)

def ph_strong_acid(c=None):
    """pH of a strong monoprotic acid. The pH of a strong monoprotic acid solution (water's own ionization included, so dilute solutions are right).
    Formula: [\\mathrm{H_3O^+}] = \\frac{c}{2} + \\sqrt{\\frac{c^2}{4} + K_w}
    Inputs:
        c: acid concentration
    Outputs: pH (pH), h ([H3O+])
    See also: help("ph_strong_acid")
    """
    given = {k: v for k, v in dict(c=c).items() if v is not None}
    return _P.solve("ph_strong_acid", **given)

def ph_strong_base(c=None, n_oh=None):
    """pH of a strong base. The pH and pOH of a strong (group 1 or 2) hydroxide solution.
    Formula: [\\mathrm{OH^-}] = n c,\\quad \\mathrm{pH} = 14 - \\mathrm{pOH}
    Inputs:
        c: base concentration
        n_oh: hydroxide ions per formula unit
    Outputs: pH (pH), pOH (pOH)
    See also: help("ph_strong_base")
    """
    given = {k: v for k, v in dict(c=c, n_oh=n_oh).items() if v is not None}
    return _P.solve("ph_strong_base", **given)

def ph_weak_acid(Ka=None, c=None):
    """pH of a weak acid. The pH and percent ionization of a weak monoprotic acid from Ka (or pKa) and its concentration.
    Formula: [\\mathrm{H_3O^+}] = \\frac{K_a c}{K_a + [\\mathrm{H_3O^+}]} + \\frac{K_w}{[\\mathrm{H_3O^+}]}
    Inputs:
        Ka: acid dissociation constant
        c: acid concentration
    Outputs: pH (pH), h ([H3O+]), percent_ionized (percent ionization)
    See also: help("ph_weak_acid")
    """
    given = {k: v for k, v in dict(Ka=Ka, c=c).items() if v is not None}
    return _P.solve("ph_weak_acid", **given)

def ph_weak_base(Kb=None, c=None):
    """pH of a weak base. The pH, pOH and percent ionization of a weak base from Kb (or pKb) and its concentration.
    Formula: [\\mathrm{OH^-}] = \\frac{K_b c}{K_b + [\\mathrm{OH^-}]} + \\frac{K_w}{[\\mathrm{OH^-}]}
    Inputs:
        Kb: base dissociation constant
        c: base concentration
    Outputs: pH (pH), pOH (pOH), percent_ionized (percent ionization)
    See also: help("ph_weak_base")
    """
    given = {k: v for k, v in dict(Kb=Kb, c=c).items() if v is not None}
    return _P.solve("ph_weak_base", **given)

def photon_energy(lam=None):
    """Energy of a photon from its wavelength. The energy (per photon and per mole of photons) and frequency of light of a given wavelength.
    Formula: E = \\frac{hc}{\\lambda}
    Inputs:
        lam: wavelength
    Outputs: E (energy per photon), E_eV (in eV), E_molar (energy per mole of photons), nu (frequency)
    See also: help("photon_energy")
    """
    given = {k: v for k, v in dict(lam=lam).items() if v is not None}
    return _P.solve("photon_energy", **given)

def photon_wavelength(E=None):
    """Wavelength of a photon from its energy. The wavelength of a photon of a given energy.
    Formula: \\lambda = \\frac{hc}{E}
    Inputs:
        E: photon energy
    Outputs: lam (wavelength), lam_nm (in nm)
    See also: help("photon_wavelength")
    """
    given = {k: v for k, v in dict(E=E).items() if v is not None}
    return _P.solve("photon_wavelength", **given)

def raoult_vapor_pressure(formula_solute=None, m_solute=None, formula_solvent=None, m_solvent=None, P0=None):
    """Vapor pressure of a solution (Raoult's law). The vapor pressure of a solvent above a solution of a nonvolatile solute, from the masses of both.
    Formula: P = x_{\\text{solvent}} P^\\circ
    Inputs:
        formula_solute: formula of the solute
        m_solute: mass of solute
        formula_solvent: formula of the solvent
        m_solvent: mass of solvent
        P0: vapor pressure of the pure solvent
    Outputs: P (vapor pressure of the solution), dP (vapor pressure lowering)
    See also: help("raoult_vapor_pressure")
    """
    given = {k: v for k, v in dict(formula_solute=formula_solute, m_solute=m_solute, formula_solvent=formula_solvent, m_solvent=m_solvent, P0=P0).items() if v is not None}
    return _P.solve("raoult_vapor_pressure", **given)

def reaction_enthalpy_from_formation(equation=None, values=None):
    """Reaction enthalpy from enthalpies of formation (Hess's law). The standard reaction enthalpy from the standard enthalpies of formation of every species (balanced equation).
    Formula: \\Delta H^\\circ_{rxn} = \\sum \\nu_p \\Delta H_f^\\circ(p) - \\sum \\nu_r \\Delta H_f^\\circ(r)
    Inputs:
        equation: balanced equation
        values: standard enthalpy of formation of each species in the order written (kJ/mol)
    Outputs: dH (standard reaction enthalpy), dH_kJ (in kJ/mol)
    See also: help("reaction_enthalpy_from_formation")
    """
    given = {k: v for k, v in dict(equation=equation, values=values).items() if v is not None}
    return _P.solve("reaction_enthalpy_from_formation", **given)

def reaction_order_from_rates(c1=None, r1=None, c2=None, r2=None):
    """Reaction order from initial rates. The order with respect to one reactant from two initial-rate experiments (other concentrations fixed).
    Formula: n = \\frac{\\ln(r_2/r_1)}{\\ln(c_2/c_1)}
    Inputs:
        c1: concentration in experiment 1
        r1: initial rate in experiment 1
        c2: concentration in experiment 2
        r2: initial rate in experiment 2
    Outputs: order (reaction order)
    See also: help("reaction_order_from_rates")
    """
    given = {k: v for k, v in dict(c1=c1, r1=r1, c2=c2, r2=r2).items() if v is not None}
    return _P.solve("reaction_order_from_rates", **given)

def rms_speed(formula=None, T=None):
    """Root-mean-square speed of gas molecules. The root-mean-square speed of the molecules of an ideal gas at a temperature.
    Formula: u_{\\text{rms}} = \\sqrt{\\frac{3RT}{M}}
    Inputs:
        formula: formula of the gas
        T: temperature
    Outputs: u_rms (root-mean-square speed)
    See also: help("rms_speed")
    """
    given = {k: v for k, v in dict(formula=formula, T=T).items() if v is not None}
    return _P.solve("rms_speed", **given)

def second_order_concentration(A0=None, k=None, t=None):
    """Second-order integrated rate law. The concentration of a reactant after a time in a second-order reaction (rate = k[A]^2).
    Formula: \\frac{1}{[A]} = \\frac{1}{[A]_0} + k t
    Inputs:
        A0: initial concentration
        k: second-order rate constant
        t: elapsed time
    Outputs: A (concentration at time t), A_molL (in mol/L)
    See also: help("second_order_concentration")
    """
    given = {k: v for k, v in dict(A0=A0, k=k, t=t).items() if v is not None}
    return _P.solve("second_order_concentration", **given)

def solute_mass_for_solution(formula=None, c=None, V=None):
    """Mass of solute for a solution. The mass of a compound needed to prepare a volume of solution of a given molarity.
    Formula: m = c V M
    Inputs:
        formula: formula of the solute
        c: molar concentration
        V: volume of solution
    Outputs: m (mass of solute), m_g (mass in grams)
    See also: help("solute_mass_for_solution")
    """
    given = {k: v for k, v in dict(formula=formula, c=c, V=V).items() if v is not None}
    return _P.solve("solute_mass_for_solution", **given)

def theoretical_yield(equation=None, reactant=None, m=None, product=None):
    """Theoretical yield from one reactant. The mass of a product formed from a given mass of one reactant (in excess of the others).
    Formula: m_P = \\frac{m_R}{M_R}\\,\\frac{\\nu_P}{\\nu_R}\\,M_P
    Inputs:
        equation: the reaction (balanced or not)
        reactant: the reactant whose mass is given
        m: mass of the reactant
        product: the product asked for
    Outputs: product_mass (theoretical mass of product), n_product (moles of product)
    See also: help("theoretical_yield")
    """
    given = {k: v for k, v in dict(equation=equation, reactant=reactant, m=m, product=product).items() if v is not None}
    return _P.solve("theoretical_yield", **given)

def titration_equivalence_volume(c_t=None, V_a=None, c_a=None, ratio=None):
    """Titration: equivalence-point volume. The volume of titrant needed to reach the equivalence point of a neutralization.
    Formula: V_{eq} = \\frac{\\nu\\, c_a V_a}{c_t}
    Inputs:
        c_t: titrant concentration
        V_a: volume of the analyte
        c_a: analyte concentration
        ratio: moles of titrant per mole of analyte
    Outputs: V_eq (titrant volume at equivalence), V_eq_mL (in mL)
    See also: help("titration_equivalence_volume")
    """
    given = {k: v for k, v in dict(c_t=c_t, V_a=V_a, c_a=c_a, ratio=ratio).items() if v is not None}
    return _P.solve("titration_equivalence_volume", **given)

def titration_ph_strong_acid_strong_base(c_a=None, V_a=None, c_b=None, V_b=None):
    """pH during a strong acid - strong base titration. The pH after adding a volume of strong base to a strong monoprotic acid (exact, any point of the titration).
    Formula: [\\mathrm{H_3O^+}] - \\frac{K_w}{[\\mathrm{H_3O^+}]} = \\frac{c_a V_a - c_b V_b}{V_a + V_b}
    Inputs:
        c_a: acid concentration
        V_a: acid volume
        c_b: base concentration
        V_b: volume of base added
    Outputs: pH (pH)
    See also: help("titration_ph_strong_acid_strong_base")
    """
    given = {k: v for k, v in dict(c_a=c_a, V_a=V_a, c_b=c_b, V_b=V_b).items() if v is not None}
    return _P.solve("titration_ph_strong_acid_strong_base", **given)

def titration_ph_weak_acid_strong_base(Ka=None, c_a=None, V_a=None, c_b=None, V_b=None):
    """pH during a weak acid - strong base titration. The pH after adding strong base to a weak monoprotic acid, at any point (exact charge balance).
    Formula: [\\mathrm{H_3O^+}] + [\\mathrm{Na^+}] = \\frac{K_w}{[\\mathrm{H_3O^+}]} + \\frac{K_a C}{K_a + [\\mathrm{H_3O^+}]}
    Inputs:
        Ka: acid dissociation constant
        c_a: acid concentration
        V_a: acid volume
        c_b: base concentration
        V_b: volume of base added
    Outputs: pH (pH)
    See also: help("titration_ph_weak_acid_strong_base")
    """
    given = {k: v for k, v in dict(Ka=Ka, c_a=c_a, V_a=V_a, c_b=c_b, V_b=V_b).items() if v is not None}
    return _P.solve("titration_ph_weak_acid_strong_base", **given)

def van_der_waals_pressure(n=None, V=None, T=None, a=None, b=None):
    """Van der Waals equation: pressure. The pressure of a real gas from the van der Waals equation (and the ideal-gas pressure for comparison).
    Formula: P = \\frac{nRT}{V - nb} - \\frac{a n^2}{V^2}
    Inputs:
        n: amount of gas
        V: volume
        T: temperature
        a: van der Waals a
        b: van der Waals b
    Outputs: P (van der Waals pressure), P_ideal (ideal-gas pressure), P_atm (van der Waals pressure in atm)
    See also: help("van_der_waals_pressure")
    """
    given = {k: v for k, v in dict(n=n, V=V, T=T, a=a, b=b).items() if v is not None}
    return _P.solve("van_der_waals_pressure", **given)

def vant_hoff_k2(K1=None, T1=None, T2=None, dH=None):
    """Van 't Hoff equation: K at another temperature. The equilibrium constant at a second temperature from K at a first one and the reaction enthalpy.
    Formula: \\ln\\frac{K_2}{K_1} = -\\frac{\\Delta H^\\circ}{R}\\left(\\frac{1}{T_2} - \\frac{1}{T_1}\\right)
    Inputs:
        K1: equilibrium constant at T1
        T1: first temperature
        T2: second temperature
        dH: standard enthalpy change
    Outputs: K2 (equilibrium constant at T2), lnK2 (ln K2)
    See also: help("vant_hoff_k2")
    """
    given = {k: v for k, v in dict(K1=K1, T1=T1, T2=T2, dH=dH).items() if v is not None}
    return _P.solve("vant_hoff_k2", **given)

def vibrational_wavenumber(molecule=None, k=None):
    """Vibrational wavenumber of a diatomic molecule. The harmonic vibrational wavenumber of a diatomic molecule from its bond force constant.
    Formula: \\tilde{\\nu} = \\frac{1}{2\\pi c}\\sqrt{\\frac{k}{\\mu}}
    Inputs:
        molecule: diatomic molecule, e.g. HCl or CO
        k: bond force constant
    Outputs: wavenumber (wavenumber), wavenumber_cm (in cm^-1), nu (vibrational frequency)
    See also: help("vibrational_wavenumber")
    """
    given = {k: v for k, v in dict(molecule=molecule, k=k).items() if v is not None}
    return _P.solve("vibrational_wavenumber", **given)

def zero_order_concentration(A0=None, k=None, t=None):
    """Zero-order integrated rate law. The concentration of a reactant after a time in a zero-order reaction.
    Formula: [A] = [A]_0 - k t
    Inputs:
        A0: initial concentration
        k: zero-order rate constant
        t: elapsed time
    Outputs: A (concentration at time t), A_molL (in mol/L)
    See also: help("zero_order_concentration")
    """
    given = {k: v for k, v in dict(A0=A0, k=k, t=t).items() if v is not None}
    return _P.solve("zero_order_concentration", **given)


